{
  "missionStatement": "Study current research on room-temperature superconductivity via online research and produce a comprehensive, evidence-based proposal for the chemistry and physics of discovering and manufacturing room-temperature superconducting compounds, updating all relevant documents in the repository.",
  "criteria": [
    {
      "description": "Online research summary document is updated with findings from at least 5 targeted web searches on recent room-temperature superconductor breakthroughs (e.g., hydrides, nickelates, cuprates) and includes citations to primary sources.",
      "expectedFiles": ["docs/online_research_summary.md"]
    },
    {
      "description": "Literature review document is updated with at least 10 new references from 2020–2025, each accompanied by a brief summary of key findings and relevance to room-temperature superconductivity.",
      "expectedFiles": ["docs/literature_review.md"]
    },
    {
      "description": "Theoretical framework document is expanded to include at least two modern theories (e.g., BCS theory, Eliashberg equations, unconventional pairing mechanisms) and explains their application to predicting room-temperature superconductivity.",
      "expectedFiles": ["docs/theoretical_framework.md"]
    },
    {
      "description": "Candidate materials document is updated with at least 5 new compounds (e.g., H3S, LaH10, nickelates, doped cuprates) including predicted Tc, synthesis conditions, and key references.",
      "expectedFiles": ["docs/candidate_materials.md"]
    },
    {
      "description": "Synthesis methods document is updated with detailed protocols for high-pressure synthesis and doping techniques for at least 3 candidate material families, referencing the candidate materials list.",
      "expectedFiles": ["docs/synthesis_methods.md"]
    },
    {
      "description": "Characterization techniques document is updated with modern methods (e.g., muon spin rotation, ARPES, transport measurements) and describes how each technique confirms superconductivity and measures critical parameters.",
      "expectedFiles": ["docs/characterization_techniques.md"]
    },
    {
      "description": "Proposed chemistry and physics document is rewritten to present a coherent, evidence-based proposal for discovering and manufacturing room-temperature superconducting compounds, covering at least three distinct material families and their manufacturing scalability.",
      "expectedFiles": ["proposed_chemistry_physics.md"]
    },
    {
      "description": "Manufacturing scalability document is updated with specific challenges (e.g., high-pressure requirements, material stability) and proposed solutions for each candidate family identified in the proposal.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Roadmap document is updated with new milestones for the next 2 years, including experimental validation, scaling, and technology transfer steps aligned with the proposed chemistry and physics.",
      "expectedFiles": ["docs/roadmap.md"]
    },
    {
      "description": "All updated documents (literature review, theoretical framework, candidate materials, synthesis methods, characterization techniques, proposed chemistry and physics, manufacturing scalability, roadmap) are cross-referenced and internally consistent.",
      "expectedFiles": []
    }
  ]
}

